(()=>{const $=s=>document.querySelector(s);const read=k=>{try{return localStorage.getItem(k)}catch{return null}};const write=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};if(read('montshire-theme')==='dark')document.body.classList.add('dark');$('.theme-toggle').onclick=()=>{document.body.classList.toggle('dark');write('montshire-theme',document.body.classList.contains('dark')?'dark':'light')};$('.mobile-menu').onclick=e=>{const on=$('#navigation').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',on)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('details[open]').forEach(x=>x.open=false);$('#navigation').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false')}});const banner=$('#cookie-banner');if(!read('montshire-consent'))banner.hidden=false;$('#cookie-settings').onclick=()=>{banner.hidden=false;banner.querySelector('button').focus()};document.querySelectorAll('[data-consent]').forEach(b=>b.onclick=()=>{write('montshire-consent',b.dataset.consent);banner.hidden=true;window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:'consent_preference',analytics_storage:b.dataset.consent==='all'?'granted':'denied'})});function event(name,details){if(read('montshire-consent')==='all'){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:name,...details})}}document.querySelectorAll('a[href^="/contact/"]').forEach(a=>a.addEventListener('click',()=>event('booking_click',{location:location.pathname})));const filter=()=>{let n=0;document.querySelectorAll('.work-card').forEach(c=>{c.hidden=($('#service-filter').value!=='all'&&c.dataset.service!==$('#service-filter').value)||($('#industry-filter').value!=='all'&&c.dataset.industry!==$('#industry-filter').value);if(!c.hidden)n++});$('#filter-status').textContent=n?`${n} case study template${n===1?'':'s'}`:'No templates match these filters.'};if($('#service-filter')){$('#service-filter').onchange=filter;$('#industry-filter').onchange=filter;filter()}let blobUrl;if($('#lead-form'))$('#lead-form').onsubmit=e=>{e.preventDefault();if(!e.target.reportValidity())return;const data=new FormData(e.target);const text=['Montshire Media — draft enquiry','This enquiry has not been submitted.','',...['name','email','company','website','budget','service','message'].map(k=>`${k.toUpperCase()}: ${data.get(k)||'Not provided'}`)].join('\n\n');if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=$('#download-enquiry');a.href=blobUrl;a.download='montshire-enquiry.txt';a.hidden=false;$('#form-status').textContent='Your enquiry is ready to download. Nothing was sent or stored by Montshire Media. Contact delivery is awaiting setup.';a.focus();event('enquiry_prepared',{location:'/contact/'})}})();
